fig2_genes <- c('ALOX5','BCL2L1','EP300','ESR1','ESR2','GSK3B','HMGCR','HSP90AA1','IKBKB','IL1B','JUN','MCL1','NFKB1','PKM','PPARA','PPARG','PRKCA','PTGES','PTGS2','STAT3')
