parse_geo <- function(g,f){
  z<-gzfile(file.path(geo_dir,f)); l<-readLines(z,warn=FALSE); close(z)
  h<-grep('^"?ID_REF"?',l)[1]; e<-grep('^!series_matrix_table_end',l,ignore.case=TRUE)[1]
  tab<-fread(text=paste(l[h:e],collapse='\n'),data.table=FALSE,check.names=FALSE)
  getv<-function(k){q<-l[startsWith(l,k)][1];if(is.na(q))return(rep(NA,ncol(tab)-1));as.character(read.delim(text=q,header=FALSE,sep='\t',quote='"',check.names=FALSE,fill=TRUE)[1,-1])}
  title<-getv('!Sample_title'); source<-getv('!Sample_source_name_ch1'); processing<-getv('!Sample_data_processing'); characteristics<-getv('!Sample_characteristics_ch1'); gsm<-colnames(tab)[-1]
  raw_group<-if(g=='GSE10474')source else if(g=='GSE32707')source else title
  label<-if(g=='GSE10474') ifelse(grepl('Acute Lung Injury|ALI',raw_group,ignore.case=TRUE),'SILI',ifelse(grepl('sepsis only',raw_group,ignore.case=TRUE),'Control',NA)) else if(g=='GSE32707') ifelse(grepl('^se/ARDS Day 0$',raw_group,ignore.case=TRUE),'SILI',ifelse(grepl('^Sepsis Day 0$',raw_group,ignore.case=TRUE),'Control','Excluded')) else ifelse(grepl('excluded',raw_group,ignore.case=TRUE),'Excluded',ifelse(grepl('with_ARDS',raw_group,ignore.case=TRUE),'SILI',ifelse(grepl('sepsis_alone',raw_group,ignore.case=TRUE),'Control',NA)))
  x<-as.matrix(tab[,-1]);storage.mode(x)<-'numeric';rownames(x)<-tab[[1]]
  patient_id<-if(g=='GSE32707') sub('^subject id: ','',characteristics) else if(g=='GSE10474') title else sub('\\..*','',title)
  exclusion_reason<-rep('Excluded: outside prespecified case definition',length(label)); exclusion_reason[!is.na(label)&label!='Excluded']<-'Included by prespecified case definition'; exclusion_reason[label=='Excluded']<-if(g=='GSE32707')'Excluded: not Day 0 Sepsis or Day 0 se/ARDS' else 'GEO excluded annotation'
  info<-data.frame(GSE=g,GSM=gsm,title=title,source=source,processing=processing,raw_group=raw_group,patient_id=patient_id,label=label,include=!is.na(label)&label!='Excluded',exclusion_reason=exclusion_reason,stringsAsFactors=FALSE)
  keep<-info$include; info<-info; list(x=x[,keep,drop=FALSE],info=info,x_all=x)
}
aggregate_probe_median<-function(x,sy){sp<-split(seq_along(sy),sy);y<-do.call(rbind,lapply(sp,function(ii)apply(x[ii,,drop=FALSE],2,median,na.rm=TRUE)));rownames(y)<-names(sp);y}
map_platform<-function(x,g){
  if(g=='GSE10474'){
    ann<-fread('data/GPL571-17391.txt',skip=16,sep='\t',header=TRUE,data.table=FALSE,fill=TRUE,quote=''); names(ann)[1]<-'PROBEID'; sym<-ann[['Gene Symbol']]; names(sym)<-ann$PROBEID; ids<-intersect(rownames(x),names(sym)); sy<-unname(sym[ids])
  } else {pkg<-switch(g,GSE32707='illuminaHumanv4.db',GSE66890='hugene10sttranscriptcluster.db'); suppressPackageStartupMessages(library(pkg,character.only=TRUE)); db<-get(pkg); ids<-intersect(rownames(x),keys(db,keytype='PROBEID')); sy<-unname(mapIds(db,ids,'SYMBOL','PROBEID',multiVals='first'))}
  ok<-!is.na(sy)&sy!=''; ids<-ids[ok]; sy<-sy[ok]; out<-aggregate_probe_median(x[ids,,drop=FALSE],sy); attr(out,'mapped_probe_count')<-length(ids); attr(out,'probe_map')<-data.frame(probe_id=ids,gene=sy); out
}
d<-lapply(names(files),function(g){a<-parse_geo(g,files[[g]]); raw<-a$x; qs<-quantile(raw,probs=c(0,.01,.25,.5,.75,.99,1),na.rm=TRUE); need_log2<-g=='GSE32707'; log2_reason<-if(g=='GSE10474')'GCRMA reported in GEO metadata; treated as log2-scale' else if(g=='GSE32707')'GenomeStudio quantile-normalized matrix has intensity-scale values; log2(x+1) applied before aggregation' else 'RMA reported in GEO metadata; treated as log2-scale'; if(need_log2) raw<-log2(raw+1); a$probe_matrix<-raw; a$preprocess<-data.frame(GSE=g,platform=if(g=='GSE10474')'GPL571' else if(g=='GSE32707')'GPL10558' else 'GPL6244',raw_probe_count=nrow(raw),raw_min=qs[1],raw_q01=qs[2],raw_q25=qs[3],raw_median=qs[4],raw_q75=qs[5],raw_q99=qs[6],raw_max=qs[7],log2_applied=need_log2,log2_reason=log2_reason,processing_metadata=substr(unique(a$info$processing)[1],1,500),aggregation='median across probes mapped to the same gene'); a$x<-map_platform(raw,g); a$platform_audit<-data.frame(GSE=g,platform=a$preprocess$platform,raw_probe_count=nrow(raw),mapped_probe_count=attr(a$x,'mapped_probe_count'),mapped_gene_count=nrow(a$x),hub_gene_coverage=sum(fig2_genes %in% rownames(a$x))); a});names(d)<-names(files)
info<-rbindlist(lapply(d,function(a)a$info),fill=TRUE); fwrite(info,file.path(outdir,'sample_metadata_full.csv')); repeat_all<-info[duplicated(paste(GSE,patient_id))|duplicated(paste(GSE,patient_id),fromLast=TRUE)]; fwrite(repeat_all,file.path(outdir,'patient_repeat_audit_all_samples.csv')); info<-info[include==TRUE]
hub_map<-rbindlist(lapply(d,function(a){pm<-attr(a$x,'probe_map'); pm[pm$gene %in% fig2_genes,,drop=FALSE]}),idcol='GSE'); fwrite(hub_map,file.path(outdir,'hub_gene_probe_mapping.csv'))
repeat_audit<-info[,.(n_GSM=.N,GSMs=paste(GSM,collapse=';')),by=.(GSE,patient_id,title,source,raw_group,label,include)]; fwrite(repeat_audit,file.path(outdir,'patient_repeat_audit.csv'))
fwrite(rbindlist(lapply(d,function(a)a$preprocess)),file.path(outdir,'preprocessing_audit.csv'))
fwrite(rbindlist(lapply(d,function(a)a$platform_audit)),file.path(outdir,'platform_mapping_audit.csv'))
ptgs2_sample<-rbindlist(lapply(d,function(a){g<-a$info[a$info$include,]; v<-as.numeric(a$x['PTGS2',]); data.frame(GSE=g$GSE,GSM=g$GSM,label=g$label,PTGS2_expression=v,PTGS2_probe_ids=paste(attr(a$x,'probe_map')$probe_id[attr(a$x,'probe_map')$gene=='PTGS2'],collapse=';'))}),fill=TRUE)
ptgs2_summary<-ptgs2_sample[,.(n=.N,mean_expression=mean(PTGS2_expression,na.rm=TRUE)),by=.(GSE,label)]; wide<-dcast(ptgs2_summary,GSE~label,value.var='mean_expression'); wide[,PTGS2_logFC_SILI_minus_Control:=SILI-Control]
hub_stats<-rbindlist(lapply(d,function(a){g<-a$info[a$info$include,]; rbindlist(lapply(fig2_genes,function(gn){v<-as.numeric(a$x[gn,]); p<-tryCatch(t.test(v[g$label=='SILI'],v[g$label=='Control'])$p.value,error=function(e)NA_real_); data.frame(GSE=g$GSE[1],gene=gn,Control_mean=mean(v[g$label=='Control'],na.rm=TRUE),SILI_mean=mean(v[g$label=='SILI'],na.rm=TRUE),logFC_SILI_minus_Control=mean(v[g$label=='SILI'],na.rm=TRUE)-mean(v[g$label=='Control'],na.rm=TRUE),P_value=p)}))}),fill=TRUE); hub_stats[,FDR:=p.adjust(P_value,'BH'),by=GSE]; fwrite(hub_stats,file.path(outdir,'hub_gene_expression_stats.csv')); fwrite(wide[hub_stats[gene=='PTGS2',.(GSE,P_value,FDR)],on='GSE'],file.path(outdir,'PTGS2_direction_summary.csv'))
ptgs2_probe<-rbindlist(lapply(d,function(a){g<-a$info[a$info$include,]; pm<-attr(a$x,'probe_map'); ids<-pm$probe_id[pm$gene=='PTGS2']; rbindlist(lapply(ids,function(id)data.frame(GSE=g$GSE,GSM=g$GSM,label=g$label,probe_id=id,expression=as.numeric(a$probe_matrix[id,g$include]))))}),fill=TRUE); ptgs2_probe_dir<-ptgs2_probe[,.(n=.N,Control_mean=mean(expression[label=='Control'],na.rm=TRUE),SILI_mean=mean(expression[label=='SILI'],na.rm=TRUE),logFC_SILI_minus_Control=mean(expression[label=='SILI'],na.rm=TRUE)-mean(expression[label=='Control'],na.rm=TRUE)),by=.(GSE,probe_id)]; fwrite(ptgs2_probe,file.path(outdir,'PTGS2_probe_expression.csv')); fwrite(ptgs2_probe_dir,file.path(outdir,'PTGS2_probe_direction.csv')); fwrite(ptgs2_sample,file.path(outdir,'PTGS2_sample_expression.csv'))
common<-Reduce(intersect,lapply(d,function(a)rownames(a$x))); X<-do.call(cbind,lapply(d,function(a)a$x[common,,drop=FALSE])); Y<-ifelse(info$label=='SILI',1,0); B<-factor(info$GSE); S<-info$GSM
X<-do.call(cbind,lapply(d,function(a)a$x[common,,drop=FALSE])); X[!is.finite(X)]<-NA
# impute only inside each training split; this global median is only a safety placeholder and is not used for modeling
folds<-createFolds(factor(Y),k=5,returnTrain=FALSE)
models<-c('DT','GBM','GLM','KNN','LASSO','NNET','RF','SVM'); method_map<-c(DT='rpart',GBM='gbm',GLM='glm',KNN='knn',LASSO='glmnet',NNET='nnet',RF='rf',SVM='svmRadial')
grid_map<-list(DT=expand.grid(cp=c(.001,.01,.05)),GBM=expand.grid(n.trees=c(50,100),interaction.depth=c(1,2),shrinkage=.05,n.minobsinnode=5),GLM=expand.grid(),KNN=expand.grid(k=c(3,5,7)),LASSO=expand.grid(alpha=1,lambda=c(.001,.01,.1)),NNET=expand.grid(size=c(2,5),decay=c(0,.01)),RF=expand.grid(mtry=c(2,4,6)),SVM=expand.grid(C=c(.1,1,10),sigma=c(.01,.1)))
fit_combat <- function(mat,tr,ap,batch,y){
  # Training-fitted batch location/scale harmonization. This is a deliberate
  # replacement for ComBat because sva::ComBat has no supported frozen-transform
  # API for applying fitted empirical-Bayes parameters to new samples.
  keep <- intersect(fig2_genes,rownames(mat)); mat<-mat[keep,,drop=FALSE]
  z<-mat[,tr,drop=FALSE]; z[!is.finite(z)]<-NA
  for(j in seq_len(nrow(z))){v<-z[j,];v[is.na(v)]<-median(v,na.rm=TRUE);if(!is.finite(v[1]))v[]<-0;z[j,]<-v}
  bt<-as.character(batch[tr]); out<-matrix(NA_real_,nrow(mat),ncol(mat),dimnames=dimnames(mat)); grand<-rowMeans(z); gsd<-apply(z,1,sd); gsd[!is.finite(gsd)|gsd==0]<-1
  for(b in unique(bt)){ii<-which(bt==b); bm<-rowMeans(z[,ii,drop=FALSE]); bs<-apply(z[,ii,drop=FALSE],1,sd); bs[!is.finite(bs)|bs==0]<-1; jj<-ap[as.character(batch[ap])==b]; if(length(jj)){raw<-mat[,jj,drop=FALSE]; raw[!is.finite(raw)]<-NA; for(j in seq_len(nrow(raw))){v<-raw[j,]; v[is.na(v)]<-median(z[j,],na.rm=TRUE); raw[j,]<-v}; out[,jj]<-sweep(sweep(raw,1,bm,'-'),1,bs,'/'); out[,jj]<-sweep(out[,jj,drop=FALSE],1,gsd,'*'); out[,jj]<-sweep(out[,jj,drop=FALSE],1,grand,'+') }}
  # Any unseen batch receives the training-global distribution without using test labels.
  unseen<-which(is.na(out[1,])); if(length(unseen)) out[,unseen]<-sweep(sweep(mat[,unseen,drop=FALSE],1,grand,'-'),1,gsd,'/')
  out[!is.finite(out)]<-0; out
}
# Numerical unit test: the held-out values may change, but training-derived
# batch means/SDs and the transformed training samples must not change.
unit_mat <- matrix(c(1,2,3,100,110,120), nrow=1, dimnames=list('PTGS2',paste0('u',1:6)))
unit_batch <- factor(c('A','A','A','B','B','B')); unit_y <- c(0,1,0,1,0,1)
u1 <- fit_combat(unit_mat, 1:4, 1:6, unit_batch, unit_y)
unit_mat_changed <- unit_mat; unit_mat_changed[,5:6] <- c(999,888)
u2 <- fit_combat(unit_mat_changed, 1:4, 1:6, unit_batch, unit_y)
stopifnot(all.equal(u1[,1:4],u2[,1:4],tolerance=1e-12)==TRUE)
unit_test_pass <- isTRUE(all.equal(u1[,1:4],u2[,1:4],tolerance=1e-12))
writeLines(if(unit_test_pass) 'PASS: held-out values do not alter training-fitted batch parameters or training transforms.' else 'FAIL', file.path(outdir,'batch_standardization_unit_test.txt'))
gene_stats<-function(z,tr,y){
  cand<-intersect(fig2_genes,rownames(z)); z<-z[cand,,drop=FALSE]
  design<-model.matrix(~factor(y[tr])); fit<-eBayes(limma::lmFit(z[,tr,drop=FALSE],design))
  tt<-limma::topTable(fit,coef=2,number=Inf,sort.by='none'); tt$gene<-rownames(tt); tt
}
select_genes<-function(z,tr,y){
  tt<-gene_stats(z,tr,y); sig<-tt$gene[tt$adj.P.Val<.05 & abs(tt$logFC)>.6]; sel<-sig; if(length(sel)<5) sel<-unique(c(sel,tt$gene[order(tt$adj.P.Val)][seq_len(min(5,nrow(tt)))])); unique(intersect(sel,fig2_genes))
}
fit_once<-function(m,x,y,tune){tc<-trainControl(method='none',classProbs=TRUE);if(m=='GLM')caret::train(x=x,y=y,method='glm',family=binomial(),trControl=tc,preProcess=c('center','scale')) else caret::train(x=x,y=y,method=method_map[[m]],tuneGrid=tune,trControl=tc,preProcess=c('center','scale'))}
outer_pred<-list(); fold_auc<-list(); inner_log<-list(); inner_split_log<-list(); sel_log<-list(); stat_log<-list(); imp_log<-list(); split_log<-list(); residual_log<-list()
for(of in seq_along(folds)){
  ot<-setdiff(seq_len(ncol(X)),folds[[of]]); oe<-folds[[of]]; infolds<-createFolds(factor(Y[ot]),k=3,returnTrain=FALSE); best<-list()
  for(m in models){gr<-grid_map[[m]]; scores<-rep(NA,nrow(gr)+if(m=='GLM')1 else 0); if(m=='GLM'){inner_log[[length(inner_log)+1]]<-data.frame(outer_fold=of,model=m,grid_id=1,inner_AUC=NA);best[[m]]<-data.frame()} else for(gi in seq_len(nrow(gr))){aa<-c();for(k in seq_along(infolds)){iv<-ot[infolds[[k]]];it<-setdiff(ot,iv);inner_split_log[[length(inner_split_log)+1]]<-data.frame(outer_fold=of,inner_fold=k,GSM=S[c(it,iv)],role=c(rep('inner_train',length(it)),rep('inner_validation',length(iv))),label=Y[c(it,iv)],GSE=B[c(it,iv)]);zc<-fit_combat(X,it,c(it,iv),B,Y);sel<-select_genes(zc,it,Y);fit<-fit_once(m,t(zc[sel,it,drop=FALSE]),factor(ifelse(Y[it]==1,'pos','neg'),levels=c('neg','pos')),gr[gi,,drop=FALSE]);pr<-predict(fit,t(zc[sel,iv,drop=FALSE]),type='prob')[,'pos'];aa<-c(aa,as.numeric(auc(Y[iv],pr,direction="<")));inner_log[[length(inner_log)+1]]<-data.frame(outer_fold=of,model=m,grid_id=gi,inner_fold=k,inner_AUC=aa[length(aa)],gr[gi,,drop=FALSE])};scores[gi]<-mean(aa)};best[[m]]<-gr[which.max(scores),,drop=FALSE]}
  zc<-fit_combat(X,ot,c(ot,oe),B,Y); tt_outer<-gene_stats(zc,ot,Y); sel<-select_genes(zc,ot,Y); tt_outer$selected<-tt_outer$gene %in% sel; tt_outer$selection_reason<-ifelse(tt_outer$selected & tt_outer$adj.P.Val<.05 & abs(tt_outer$logFC)>.6,'significant_threshold',ifelse(tt_outer$selected,'top5_rank_fallback','not_selected')); stat_log[[length(stat_log)+1]]<-data.frame(outer_fold=of,tt_outer[,c('gene','logFC','P.Value','adj.P.Val','selected','selection_reason')]); sel_log[[length(sel_log)+1]]<-data.frame(outer_fold=of,rank=seq_along(sel),gene=sel);split_log[[length(split_log)+1]]<-data.frame(outer_fold=of,GSM=S[c(ot,oe)],role=c(rep('train',length(ot)),rep('test',length(oe))),label=Y[c(ot,oe)],GSE=B[c(ot,oe)])
  for(m in models){fit<-fit_once(m,t(zc[sel,ot,drop=FALSE]),factor(ifelse(Y[ot]==1,'pos','neg'),levels=c('neg','pos')),best[[m]]);pr<-as.numeric(predict(fit,t(zc[sel,oe,drop=FALSE]),type='prob')[,'pos']);au<-as.numeric(auc(Y[oe],pr,direction="<"));outer_pred[[length(outer_pred)+1]]<-data.frame(outer_fold=of,model=m,GSM=S[oe],y=Y[oe],prob=pr,AUC=au);residual_log[[length(residual_log)+1]]<-data.frame(outer_fold=of,model=m,GSM=S[oe],residual=abs(Y[oe]-pr));for(j in seq_along(sel)){xp<-t(zc[sel,oe,drop=FALSE]);xp[,j]<-sample(xp[,j]);pp<-as.numeric(predict(fit,xp,type='prob')[,'pos']);imp_log[[length(imp_log)+1]]<-data.frame(outer_fold=of,model=m,gene=sel[j],auc_drop=au-as.numeric(auc(Y[oe],pp,direction="<")))}}
}
pred<-rbindlist(outer_pred); fa<-unique(pred[,.(outer_fold,model,AUC)]); fwrite(pred,file.path(outdir,'outer_test_predictions.csv')); fwrite(rbindlist(split_log),file.path(outdir,'outer_fold_splits.csv')); fwrite(rbindlist(sel_log),file.path(outdir,'outer_training_gene_selection.csv')); fwrite(rbindlist(stat_log),file.path(outdir,'outer_training_gene_statistics.csv')); fwrite(rbindlist(inner_split_log,fill=TRUE),file.path(outdir,'inner_fold_splits.csv')); fwrite(rbindlist(inner_log,fill=TRUE),file.path(outdir,'inner_tuning_results.csv')); fwrite(rbindlist(imp_log),file.path(outdir,'outer_test_permutation_importance.csv')); fwrite(rbindlist(residual_log),file.path(outdir,'outer_test_residuals.csv')); fwrite(fa,file.path(outdir,'fold_auc.csv')); fwrite(fa[,.(mean_AUC=mean(AUC),sd_AUC=sd(AUC)),by=model],file.path(outdir,'model_summary.csv'))
auto_checks<-c(); pa<-fread(file.path(outdir,'platform_mapping_audit.csv')); allinfo<-fread(file.path(outdir,'sample_metadata_full.csv')); inc<-allinfo[include==TRUE]; auto_checks<-c(auto_checks,if(all(pa$platform==c('GPL571','GPL10558','GPL6244')))'PASS platform IDs' else 'FAIL platform IDs',if(all(pa$hub_gene_coverage==20))'PASS all 20 Hub genes mapped' else 'FAIL Hub gene coverage',if(!anyDuplicated(allinfo$GSM))'PASS unique GSM IDs' else 'FAIL duplicate GSM IDs',if(!anyDuplicated(paste(inc$GSE,inc$patient_id)))'PASS no included patient duplicates' else 'FAIL patient duplicate review required',if(nrow(inc)==139)'PASS prespecified included sample count 139' else paste('FAIL included sample count',nrow(inc)),if(all(fread(file.path(outdir,'outer_training_gene_statistics.csv'))$gene %in% fig2_genes))'PASS candidate gene restriction' else 'FAIL candidate gene restriction'); recomputed<-pred[,.(recomputed_AUC=as.numeric(auc(y,prob,direction='<'))),by=.(outer_fold,model)]; mm<-merge(fa,recomputed,by=c('outer_fold','model')); auto_checks<-c(auto_checks,if(max(abs(mm$AUC-mm$recomputed_AUC))<1e-10)'PASS fold AUC reproducibility' else 'FAIL fold AUC reproducibility',if(all(fread(file.path(outdir,'preprocessing_audit.csv'))$log2_applied %in% c(TRUE,FALSE)))'PASS explicit per-dataset log2 decision' else 'FAIL log2 decision'); writeLines(auto_checks,file.path(outdir,'automatic_checks.txt')); writeLines(capture.output(sessionInfo()),file.path(outdir,'sessionInfo.txt')); saveRDS(list(seed=20261107,outer=5,inner=3,models=models,figure2_genes=fig2_genes,common_genes=length(common),batch_method='training-fitted per-batch location/scale harmonization; no ComBat transform applied to test data',probe_aggregation='median per gene after per-dataset scale assessment'),file.path(outdir,'run_manifest.rds'))
